import { useRef } from 'react'
import { useAssistantStore } from '@/app/store/assistantStore'
import { Send, Paperclip, Mic } from 'lucide-react'

export function AssistantComposer() {
  const { draft, setDraft, addMessage, isLoading } = useAssistantStore()
  const inputRef = useRef<HTMLTextAreaElement>(null)

  const handleSend = () => {
    const text = draft.trim()
    if (!text || isLoading) return

    addMessage({
      id: crypto.randomUUID(),
      role: 'user',
      content: text,
      timestamp: new Date().toISOString(),
    })

    setDraft('')

    // Simulated response — replace with real backend call
    setTimeout(() => {
      addMessage({
        id: crypto.randomUUID(),
        role: 'assistant',
        content: `I can help with: "${text}". Connect the backend assistant service to enable full AI responses.`,
        timestamp: new Date().toISOString(),
        actionMode: 'suggest',
      })
    }, 800)
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }

  return (
    <div className="border-t border-border p-2.5">
      <div className="flex items-end gap-1.5 rounded-xl border border-border bg-background focus-within:border-accent/50 transition-colors">
        <textarea
          ref={inputRef}
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Ask your companion..."
          rows={1}
          className="flex-1 resize-none bg-transparent px-3 py-2 text-sm outline-none placeholder:text-muted-foreground min-h-[36px] max-h-[120px]"
        />
        <div className="flex items-center gap-0.5 pb-1.5 pr-1.5">
          <button className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground">
            <Paperclip size={14} />
          </button>
          <button className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground">
            <Mic size={14} />
          </button>
          <button
            onClick={handleSend}
            disabled={!draft.trim() || isLoading}
            className="p-1.5 rounded-lg bg-accent text-accent-foreground disabled:opacity-40 hover:opacity-90 transition-opacity"
          >
            <Send size={14} />
          </button>
        </div>
      </div>
    </div>
  )
}
